}

use std::fmt;
use std::num::ParseIntError;

#[derive(Debug)]
enum AgeError {
    NotANumber(ParseIntError),
    OutOfRange(i64),
}

impl fmt::Display for AgeError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            AgeError::NotANumber(e) => write!(f, "not a number: {e}"),
            AgeError::OutOfRange(n) => write!(f, "{n} is not a believable age"),
        }
    }
}

impl std::error::Error for AgeError {}

impl From<ParseIntError> for AgeError {
    fn from(e: ParseIntError) -> Self {
        AgeError::NotANumber(e)
    }
}

fn parse_age(text: &str) -> Result<u8, AgeError> {
    let n = text.trim().parse::<i64>()?; // ? converts a ParseIntError with From
    if !(0..=150).contains(&n) {
        return Err(AgeError::OutOfRange(n));
    }
    Ok(n as u8)
}

fn find_user(id: u32) -> Option<&'static str> {
    match id {
        1 => Some("ana"),
        2 => Some("rui"),
        _ => None,
    }
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    for text in ["42", "abc", "200"] {
        match parse_age(text) {
            Ok(age) => println!("age {age}"),
            Err(e) => println!("error: {e}"),
        }
