    let name = find_user(3).unwrap_or("guest");
    let upper = find_user(1).map(|n| n.to_uppercase());
    println!("{name} {upper:?}");

    let found = find_user(2).ok_or("no such user")?;
    println!("found {found}");

    let age = parse_age("37")?; // in main, ? returns the error from main
    println!("next year: {}", age + 1);
    Ok(())
}

