#[derive(Debug, PartialEq)]
enum ParseError {
    Empty,
    UnknownCommand(String),
    MissingArgument(&'static str),
    BadNumber(String),
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        // TODO: match on self and write a message for each variant:
        //   Empty                  -> empty line
        //   UnknownCommand(c)      -> unknown command "c"
        //   MissingArgument(name)  -> "name" needs an argument
        //   BadNumber(text)        -> "text" is not a number
        write!(f, "{self:?}")
    }
}

/// Parses one line such as "forward 3", "turn left" or "say hello there".
fn parse(line: &str) -> Result<Command, ParseError> {
    let mut words = line.split_whitespace();
    let Some(first) = words.next() else {
        return Err(ParseError::Empty);
    };
    // TODO: match on first:
    //   "forward": the next word is a number of steps (MissingArgument("forward") if there's
    //              none, BadNumber if it doesn't parse as a u32); use ok_or and map_err with ?
    //   "turn":    the next word is "left" or "right"; anything else is UnknownCommand("turn ...")
    //              and nothing at all is MissingArgument("turn")
    //   "say":     the rest of the words, joined with spaces (MissingArgument("say") if empty)
    //   anything else: UnknownCommand
    Err(ParseError::UnknownCommand(first.to_string()))
}

struct Robot {
