        //       (Direction::North, Turn::Right) => Direction::East
        let _ = turn;
    }

    /// Carries out a command; returns what the robot says, if anything.
    fn run(&mut self, command: &Command) -> Option<String> {
        // TODO: Forward(n) moves n steps the way the robot faces (north adds to y, east to x,
        //       south takes from y, west from x); Turn calls self.turn; Say returns
        //       Some(format!("robot says: {text}")). Only Say returns Some.
        let _ = command;
        None
    }
}

const PROGRAM: &str = "forward 3
turn right
forward 2
say hello there
jump 4
forward
turn around
forward x2

turn left
turn left
forward 1";

fn main() {
    let mut robot = Robot::new();
    for (i, line) in PROGRAM.lines().enumerate() {
        match parse(line) {
            Ok(command) => {
                if let Some(message) = robot.run(&command) {
                    println!("{message}");
                }
            }
            Err(e) => println!("line {}: {e}", i + 1),
        }
    }
    println!(
        "robot at ({}, {}) facing {:?}",
