trait Summary {
    fn author(&self) -> String;

    // A default method: implementors get it for free, and can override it.
    fn summarise(&self) -> String {
        format!("(read more from {}...)", self.author())
    }
}

struct Article {
    title: String,
    author: String,
}

struct Post {
    user: String,
    text: String,
}

impl Summary for Article {
    fn author(&self) -> String {
        self.author.clone()
    }

    fn summarise(&self) -> String {
        format!("{}, by {}", self.title, self.author)
    }
}

impl Summary for Post {
    fn author(&self) -> String {
        format!("@{}", self.user)
    }
}

// Static dispatch: the compiler makes a version of notify for each type it's used with.
fn notify(item: &impl Summary) {
    println!("Breaking news! {}", item.summarise());
}

fn main() {
    let article = Article {
        title: String::from("The 2024 edition"),
        author: String::from("Wei"),
    };
    let post = Post {
        user: String::from("jae"),
        text: String::from("Traits are great"),
    };
    println!("{}", post.text);
    notify(&article);
    notify(&post);

    // Dynamic dispatch: different types behind one trait, in one vector.
    let feed: Vec<Box<dyn Summary>> = vec![Box::new(article), Box::new(post)];
    for item in &feed {
        println!("{}", item.summarise());
    }
}

