        Point { x, y }
    }
}

// Works for any T that can be compared and copied.
fn largest<T: PartialOrd + Copy>(items: &[T]) -> Option<T> {
    let mut best = *items.first()?;
    for &item in items {
        if item > best {
            best = item;
        }
    }
    Some(best)
}

struct Pair<T> {
    a: T,
    b: T,
}

impl<T> Pair<T>
where
    T: PartialOrd + fmt::Display,
{
    fn larger(&self) -> String {
        if self.a >= self.b {
            self.a.to_string()
        } else {
            self.b.to_string()
        }
    }
}

fn main() {
    let p = Point { x: 1, y: 2 } + Point::from((10, 20));
    println!("{p} {p:?} {}", Point::default());
    let q: Point = (3, 4).into();
    println!("{}", p == q);

    println!(
        "{:?} {:?} {:?}",
        largest(&[3, 9, 4]),
        largest(&[1.5, 0.5]),
        largest::<char>(&[])
    );
    println!(
        "{}",
        Pair {
            a: "pear",
            b: "apple"
        }
        .larger()
    );
}

