fn apply_twice<F: Fn(i32) -> i32>(f: F, x: i32) -> i32 {
    f(f(x))
}

fn make_adder(n: i32) -> impl Fn(i32) -> i32 {
    move |x| x + n // move: the closure takes ownership of n
}

fn main() {
    let double = |x| x * 2;
    println!("{}", apply_twice(double, 3));
    println!("{}", apply_twice(make_adder(10), 1));

    let mut count = 0;
    let mut tick = || count += 1; // FnMut: it changes what it captured
    tick();
    tick();
    println!("ticked {count} times");

    let name = String::from("Ana");
    let greet = move || format!("hello, {name}"); // name moves into the closure
    println!("{}", greet());

    let mut people = vec![("Rui", 31), ("Ana", 27), ("Eva", 35)];
    people.sort_by_key(|&(_, age)| age);
    println!("{people:?}");

    let consume = move || drop(people); // FnOnce: it gives away what it owns
    consume();
}

struct Countdown {
    from: u32,
}

impl Iterator for Countdown {
    type Item = u32;

    fn next(&mut self) -> Option<u32> {
        if self.from == 0 {
            None
        } else {
            self.from -= 1;
            Some(self.from + 1)
        }
    }
}

fn main() {
