}

/// The n most frequent words, most frequent first, with ties in alphabetical order.
fn top(counts: &HashMap<String, usize>, n: usize) -> Vec<(&str, usize)> {
    // TODO: collect (word, count) pairs into a Vec, sort it with
    // sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(b.0))), and keep the first n
    let _ = (counts, n);
    Vec::new()
}

fn main() {
    let stop: HashSet<&str> = STOP_WORDS.into_iter().collect();
    let counts = count_words(TEXT, &stop);

    let total: usize = counts.values().sum();
    let letters: usize = counts.iter().map(|(w, c)| w.chars().count() * c).sum();
    println!("words counted: {total} ({} different)", counts.len());
    if total > 0 {
        println!("average length: {:.2}", letters as f64 / total as f64);
    }
    let longest = counts.keys().map(|w| w.chars().count()).max().unwrap_or(0);
    let mut long_words: Vec<&String> = counts
        .keys()
        .filter(|w| w.chars().count() == longest)
        .collect();
    long_words.sort();
    println!("longest: {long_words:?}");
    println!("top 5:");
    for (word, count) in top(&counts, 5) {
        println!("  {word:<8} {count}");
    }
}

