//! Temperature readings and conversions.

pub mod convert;

/// One temperature reading from a named sensor.
pub struct Reading {
    pub sensor: String,
    pub celsius: f64,
}

impl Reading {
    pub fn new(sensor: &str, celsius: f64) -> Self {
        Reading {
            sensor: sensor.to_string(),
            celsius,
        }
    }

    pub fn fahrenheit(&self) -> f64 {
        convert::c_to_f(self.celsius)
    }
}

/// Converts degrees Celsius to degrees Fahrenheit, rounded to one decimal place.
///
/// ```
/// assert_eq!(temps::convert::c_to_f(100.0), 212.0);
/// ```
pub fn c_to_f(celsius: f64) -> f64 {
    round1(celsius * 9.0 / 5.0 + 32.0)
}

/// The mean of some temperatures. Panics if there are none.
pub fn average(celsius: &[f64]) -> f64 {
    assert!(!celsius.is_empty(), "no readings to average");
    celsius.iter().sum::<f64>() / celsius.len() as f64
}

// Private: only code in this module (and its tests) can call it.
fn round1(x: f64) -> f64 {
    (x * 10.0).round() / 10.0
}

use temps::Reading;

fn main() {
    let readings = [Reading::new("kitchen", 21.5), Reading::new("garden", -3.0)];
    for r in &readings {
        println!("{}: {} °C = {} °F", r.sensor, r.celsius, r.fahrenheit());
    }
}

#[cfg(test)]
mod tests {
    use super::*; // the tests module can see the private items of its parent

    #[test]
    fn freezing_point() {
        assert_eq!(c_to_f(0.0), 32.0);
    }

    #[test]
    fn rounds_to_one_decimal() {
        assert_eq!(round1(70.66), 70.7);
    }

    #[test]
    #[should_panic(expected = "no readings")]
    fn average_of_nothing_panics() {
        average(&[]);
    }
}

// An integration test: it uses the library only through its public API.
use temps::Reading;

#[test]
fn a_reading_converts_to_fahrenheit() {
    let r = Reading::new("office", 37.0);
    assert_eq!(r.fahrenheit(), 98.6);
}

use std::env;
use std::error::Error;
use std::fs;
use std::process::ExitCode;

fn count(path: &str) -> Result<(usize, usize, usize), Box<dyn Error>> {
    let text = fs::read_to_string(path).map_err(|e| format!("could not read {path}: {e}"))?;
    Ok((
        text.lines().count(),
        text.split_whitespace().count(),
        text.chars().count(),
    ))
}

fn main() -> ExitCode {
    let args: Vec<String> = env::args().collect();
    let Some(path) = args.get(1) else {
        eprintln!("usage: wc FILE");
        return ExitCode::from(2);
    };
    match count(path) {
        Ok((lines, words, chars)) => {
            println!("{lines} lines, {words} words, {chars} characters in {path}");
            ExitCode::SUCCESS
        }
        Err(e) => {
            eprintln!("error: {e}");
            ExitCode::FAILURE
        }
    }
}

