//! Summarise a numeric column of a CSV file.

use std::fmt;

/// What can go wrong while summarising.
#[derive(Debug, PartialEq)]
pub enum SummaryError {
    NoHeader,
    MissingColumn(String),
    BadNumber { line: usize, value: String },
    NoRows,
}

impl fmt::Display for SummaryError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            SummaryError::NoHeader => write!(f, "the file is empty"),
            SummaryError::MissingColumn(c) => write!(f, "no column called \"{c}\""),
            SummaryError::BadNumber { line, value } => {
                write!(f, "line {line}: \"{value}\" is not a number")
            }
            SummaryError::NoRows => write!(f, "no rows to summarise"),
        }
    }
}

impl std::error::Error for SummaryError {}

/// The count, minimum, maximum and mean of a column.
#[derive(Debug, PartialEq)]
pub struct Summary {
    pub count: usize,
    pub min: f64,
    pub max: f64,
    pub mean: f64,
}

/// Finds `column` in a comma-separated header line and returns its position.
pub fn column_index(header: &str, column: &str) -> Result<usize, SummaryError> {
    // TODO: split the header on ',', and return the position of the name that, trimmed,
    // equals column (the iterator method position helps), or
    // Err(SummaryError::MissingColumn(column.to_string())) if there's none
    let _ = (header, column);
    Err(SummaryError::NoHeader)
}

/// Summarises the named column of CSV text whose first line is a header.
///
/// ```
/// let s = csvsum::summarise("item,price\ntea,2.5\ncake,3.5\n", "price").unwrap();
/// assert_eq!(s.count, 2);
/// assert_eq!(s.mean, 3.0);
/// ```
pub fn summarise(text: &str, column: &str) -> Result<Summary, SummaryError> {
    let mut lines = text.lines();
    let header = lines.next().ok_or(SummaryError::NoHeader)?;
    let index = column_index(header, column)?;
    // TODO: for each remaining line that isn't blank (number them with enumerate: the first
    // data line is line 2 of the file), take field number index, trim it and parse it as an
    // f64; a missing or unparsable field is Err(SummaryError::BadNumber { line, value }).
    // Return Err(SummaryError::NoRows) if there were no values, otherwise the Summary.
    let _ = index;
    Err(SummaryError::NoRows)
}

#[cfg(test)]
mod tests {
    // TODO: add a unit test called column_index_ignores_spaces that checks
    // column_index("date, units ,price", "units") is Ok(1). Start with use super::*;
}

use std::env;
use std::fs;
use std::process::ExitCode;

fn main() -> ExitCode {
    let args: Vec<String> = env::args().skip(1).collect();
    let [path, column] = args.as_slice() else {
        eprintln!("usage: csvsum FILE COLUMN");
        return ExitCode::from(2);
    };
    let text = match fs::read_to_string(path) {
        Ok(text) => text,
        Err(e) => {
            eprintln!("error: could not read {path}: {e}");
            return ExitCode::FAILURE;
        }
    };
    match csvsum::summarise(&text, column) {
        Ok(s) => {
            println!(
                "{column}: {} rows, min {:.2}, max {:.2}, mean {:.2}",
                s.count, s.min, s.max, s.mean
            );
            ExitCode::SUCCESS
        }
        Err(e) => {
            eprintln!("error: {e}");
            ExitCode::FAILURE
        }
    }
}

// Integration tests: they use csvsum only through its public API, as any other crate would.
use csvsum::{Summary, SummaryError, column_index, summarise};

const SALES: &str = "date,product,units,price
2026-03-01,tea,12,3.50
2026-03-01,coffee,8,4.20
2026-03-02,tea,15,3.40
";

#[test]
fn finds_a_column() {
    assert_eq!(column_index("date,product,units,price", "units"), Ok(2));
}

#[test]
fn reports_a_missing_column() {
    assert_eq!(
        column_index("a,b", "c"),
        Err(SummaryError::MissingColumn("c".into()))
    );
}

#[test]
fn summarises_a_column() {
    let s = summarise(SALES, "units").unwrap();
    assert_eq!(
        s,
        Summary {
            count: 3,
            min: 8.0,
            max: 15.0,
            mean: 35.0 / 3.0
        }
    );
}

#[test]
fn reports_the_line_of_a_bad_number() {
    let result = summarise("units\n4\nlots\n", "units");
    assert_eq!(
        result,
        Err(SummaryError::BadNumber {
            line: 3,
            value: "lots".into()
        })
    );
}

#[test]
fn skips_blank_lines_but_needs_rows() {
    assert_eq!(summarise("units\n\n", "units"), Err(SummaryError::NoRows));
}
